 class eventclass_asistencias  extends eventsBase
{
	function __construct()
	{
	// fill list of events
		$this->events["BeforeQueryList"]=true;

		$this->events["BeforeAdd"]=true;

		$this->events["BeforeShowList"]=true;

		$this->events["BeforeMoveNextList"]=true;



	}

//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// List page: Before SQL query
function BeforeQueryList(&$strSQL, &$strWhereClause, &$strOrderBy, &$pageObject)
{

		if ($_SESSION["rol"] == 'Docente') {
    $strWhereClause = whereAdd($strWhereClause, "inscripcion_id IN (SELECT i.id FROM inscripciones i INNER JOIN cursos c ON c.id = i.curso_id WHERE c.profesor_id = " . intval($_SESSION["profesor_id"]) . ")");
} elseif ($_SESSION["rol"] == 'Alumno') {
    $strWhereClause = whereAdd($strWhereClause, "inscripcion_id IN (SELECT id FROM inscripciones WHERE estudiante_id = " . intval($_SESSION["estudiante_id"]) . ")");
}
;		
} // function BeforeQueryList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$insc_id = intval($values["inscripcion_id"]);
$fecha   = $values["fecha"];
$hoy     = date("Y-m-d");

if (empty($fecha)) {
    $fecha = $hoy;
    $values["fecha"] = $hoy;
}

if ($fecha > $hoy) {
    $message = "No puede asentar asistencias con fecha futura.";
    return false;
}

// Evitar duplicar asistencia para el mismo alumno en la misma fecha
$rsDup = DB::Query("SELECT id FROM asistencias WHERE inscripcion_id = " . $insc_id . " AND fecha = " . db_prepare_string($fecha) . " LIMIT 1");
if ($rsDup->fetchAssoc()) {
    $message = "Ya existe un registro de asistencia para este alumno en la fecha " . date("d/m/Y", strtotime($fecha)) . ".";
    return false;
}

if (empty($values["estado"])) {
    $values["estado"] = "Presente";
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before display
function BeforeShowList(&$xt, &$templatefile, &$pageObject)
{

		$rol_actual = isset($_SESSION["rol"]) ? $_SESSION["rol"] : "Invitado";
$pageObject->setProxyValue("user_rol", $rol_actual);

if ($rol_actual != "Admin" && $rol_actual != "Docente") {
    $pageObject->hideItem("custom_button");
}
;		
} // function BeforeShowList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// List page: After record processed
function BeforeMoveNextList(&$data, &$row, &$record, $recordId, &$pageObject)
{

		// Si tenemos el cálculo de porcentaje en la fila:
$porc = isset($data["porcentaje"]) ? intval($data["porcentaje"]) : 85; 
$barColor = ($porc >= 70) ? "progress-bar-success" : "progress-bar-danger";

$row["asistencia_grafica"] = '
<div style="min-width: 110px;">
    <div class="progress" style="height: 14px; margin-bottom: 2px; background: #e0e0e0;">
        <div class="progress-bar ' . $barColor . '" role="progressbar" style="width: ' . $porc . '%; font-size: 10px; line-height: 14px;">
            ' . $porc . '%
        </div>
    </div>
</div>';
;		
} // function BeforeMoveNextList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



